      {
        "title": "Lack of concordance among infant social attention measures | Scientific Reports",
        "url": "https://www.nature.com/articles/s41598-026-36807-5",
        "description": "In this study, we <strong>assessed 50 ten-month-old infants using three common measures of social visual attention: eye (versus mouth) preference, gaze following, and face preference (versus non-social objects).</strong>",
        "position": 4
      },
